# Initially generated by GitHub Copilot.
import io
import os
import tempfile
import unittest

from tmpl_survey import survey_dot
from tmpl_survey import dot_node_collapse


class TestTmplSurveyFocusedTargets(unittest.TestCase):
    def test_focused_targets_include_trial_templates(self):
        got = [(x.tmpl_name, x.slug, x.collapse) for x in survey_dot._FOCUSED_TARGETS]
        expected = [
            ("מ:כפול", "dualcant", False),
            ("נוסח", "docnote", True),
            ("מ:פסוק", "mpasuq", False),
            ("כו״ק", "kvq", False),
            ("מ:דחי", "dexi", False),
        ]
        self.assertEqual(expected, got)

    def test_write_focused_dot_files_writes_all_expected_dots(self):
        stack_counts = {
            ("מ:כפול", "C"): 1,
            ("נוסח", "C"): 1,
            ("מ:פסוק", "D"): 1,
            ("כו״ק", "E"): 1,
            ("מ:דחי", "E"): 1,
        }
        slugs = [x.slug for x in survey_dot._FOCUSED_TARGETS]

        with tempfile.TemporaryDirectory() as tdir:
            stem = os.path.join(tdir, "plain")
            svg_stem = os.path.join(tdir, "svg", "plain")
            os.makedirs(os.path.dirname(svg_stem), exist_ok=True)

            render_calls = []
            orig_render_svg = survey_dot.render_svg
            survey_dot.render_svg = (
                lambda dot_path, svg_path, generator_file=None: render_calls.append(
                    (dot_path, svg_path, generator_file)
                )
            )
            try:
                survey_dot.write_focused_dot_files(
                    stack_counts, stem, svg_stem=svg_stem
                )
            finally:
                survey_dot.render_svg = orig_render_svg

            for slug in slugs:
                dot_path = f"{stem}-{slug}-call-graph.dot"
                self.assertTrue(os.path.exists(dot_path), dot_path)

            self.assertEqual(len(slugs), len(render_calls))

    def test_focused_edge_extraction_matches_docnote_suffixes(self):
        stack_counts = {
            ("מ:דחי", "C/נוסח@1"): 3,
            ("מ:עלייה", "C/נוסח@2/מ:דחי"): 5,
        }

        edges = survey_dot._focused_edges_from_stack_counts(stack_counts, target="נוסח")

        self.assertEqual(3, edges[("נוסח@1", "מ:דחי")])
        self.assertEqual(5, edges[("נוסח@2", "מ:דחי")])
        self.assertEqual(5, edges[("מ:דחי", "מ:עלייה")])

    def test_full_graph_explicit_node_group_collapse_merges_named_nodes(self):
        edges = {
            ("כו״ק", "X"): 7,
            ("קו״כ", "X"): 11,
            ("מ:קו״כ-אם-2", "X"): 13,
        }

        collapsed_edges, groups = dot_node_collapse.collapse_edges_for_output(
            edges,
            {"C", "D", "E"},
            collapse_node_groups=(("כו״ק", "קו״כ", "מ:קו״כ-אם-2"),),
        )

        self.assertEqual(31, collapsed_edges[("כו״ק", "X")])
        self.assertNotIn(("קו״כ", "X"), collapsed_edges)
        self.assertNotIn(("מ:קו״כ-אם-2", "X"), collapsed_edges)
        self.assertEqual(["כו״ק", "מ:קו״כ-אם-2", "קו״כ"], groups["כו״ק"])

    def test_node_mode_edge_extraction_keeps_column_roots_from_longer_stacks(self):
        stack_counts = {
            ("A", "E"): 2,
            ("B", "E/A"): 3,
        }

        edges = survey_dot._edges_from_stack_counts(stack_counts, discarded=set())

        # Column letters partition graph versions; they are not emitted as nodes.
        self.assertNotIn(("E", "A"), edges)
        self.assertEqual(3, edges[("A", "B")])

    def test_focused_dexi_graph_excludes_cross_stack_transitive_leakage(self):
        stack_counts = {
            ("נוסח", "C"): 2,
            ("נוסח", "D"): 3,
            ("נוסח", "E"): 5,
            ("מ:דחי", "E/נוסח"): 7,
            ("מ:אות-ג", "E/נוסח/מ:דחי"): 11,
            ("מ:אות-ס", "E/נוסח/מ:דחי/מ:אות-ג"): 13,
        }

        with tempfile.TemporaryDirectory() as tdir:
            stem = os.path.join(tdir, "plain")
            orig_render_svg = survey_dot.render_svg
            survey_dot.render_svg = lambda dot_path, svg_path, generator_file=None: None
            try:
                survey_dot.write_focused_dot_files(stack_counts, stem, svg_stem=stem)
            finally:
                survey_dot.render_svg = orig_render_svg

            dexi_dot_path = f"{stem}-dexi-call-graph.dot"
            with open(dexi_dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertIn('"מ:דחי" -> "מ:אות-ג" [label="24"]', dot_text)
        self.assertIn('"מ:אות-ג" -> "מ:אות-ס" [label="13"]', dot_text)
        self.assertNotIn('"C" -> "נוסח"', dot_text)
        self.assertNotIn('"D" -> "נוסח"', dot_text)
        self.assertNotIn('"E" ->', dot_text)
        self.assertNotIn('"נוסח"', dot_text)
        self.assertIn("מ:כפול, נוסח have been discarded", dot_text)

    def test_focused_docnote_uses_targeted_discard_set(self):
        stack_counts = {
            ("נוסח@1", "C"): 2,
            ("נוסח@2", "C"): 4,
            ("מ:דחי", "C/נוסח@1"): 3,
            ("מ:עלייה", "C/נוסח@2"): 7,
        }

        with tempfile.TemporaryDirectory() as tdir:
            stem = os.path.join(tdir, "plain")
            orig_render_svg = survey_dot.render_svg
            survey_dot.render_svg = lambda dot_path, svg_path, generator_file=None: None
            try:
                survey_dot.write_focused_dot_files(stack_counts, stem, svg_stem=stem)
            finally:
                survey_dot.render_svg = orig_render_svg

            docnote_dot_path = f"{stem}-docnote-call-graph.dot"
            with open(docnote_dot_path, encoding="utf-8") as dot_fp:
                dot_text = dot_fp.read()

        self.assertNotIn('"C" -> "נוסח@1"', dot_text)
        self.assertNotIn('"C" -> "נוסח@2"', dot_text)
        self.assertIn('"נוסח@2" -> "מ:עלייה" [label="7"]', dot_text)
        self.assertNotIn('"נוסח@1" -> "מ:דחי" [label="3"]', dot_text)
        self.assertIn("כו״ק", dot_text)
        self.assertIn("מ:קו״כ-אם-2", dot_text)
        self.assertIn("מ:כו״ק מיוחד", dot_text)
        self.assertIn("מ:קמץ", dot_text)
        self.assertIn("מ:דחי", dot_text)
        self.assertIn("have been discarded", dot_text)

